import 'package:flutter/material.dart';

void main() => runApp(const KantinApp());

const _orange = Color(0xFFE86F32);
const _cream = Color(0xFFFFF8F0);
const _ink = Color(0xFF292522);

class Food {
  final String name, category, description, emoji;
  final int price;
  final double rating;
  const Food(this.name, this.category, this.description, this.emoji, this.price, this.rating);
}

const foods = <Food>[
  Food('Nasi Ayam Bakar', 'Makanan', 'Ayam bakar berbumbu, nasi hangat, lalapan, dan sambal khas Bu Sari.', '🍗', 18000, 4.9),
  Food('Nasi Goreng Spesial', 'Makanan', 'Nasi goreng rumahan dengan telur, sayuran, dan kerupuk renyah.', '🍳', 15000, 4.8),
  Food('Mie Goreng Jawa', 'Makanan', 'Mie goreng dengan bumbu Jawa, sayuran segar, dan taburan bawang goreng.', '🍜', 14000, 4.7),
  Food('Soto Ayam', 'Makanan', 'Soto ayam hangat dengan suwiran ayam, soun, dan jeruk nipis.', '🍲', 16000, 4.8),
  Food('Es Teh Manis', 'Minuman', 'Teh pilihan dengan es batu, segar untuk menemani makan siang.', '🧋', 5000, 4.6),
  Food('Jus Alpukat', 'Minuman', 'Jus alpukat lembut yang dibuat saat dipesan.', '🥑', 10000, 4.7),
  Food('Pisang Goreng', 'Camilan', 'Pisang matang berbalut adonan renyah, cocok untuk teman santai.', '🍌', 8000, 4.6),
  Food('Tahu Isi', 'Camilan', 'Tahu goreng berisi sayuran gurih dan disajikan hangat.', '🥟', 7000, 4.5),
];

String rupiah(int value) => 'Rp${value.toString().replaceAllMapped(RegExp(r'\B(?=(\d{3})+(?!\d))'), (_) => '.')}';

class KantinApp extends StatelessWidget {
  const KantinApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(
    title: 'Kantin Bu Sari', debugShowCheckedModeBanner: false,
    theme: ThemeData(useMaterial3: true, colorScheme: ColorScheme.fromSeed(seedColor: _orange), scaffoldBackgroundColor: _cream,
      appBarTheme: const AppBarTheme(backgroundColor: _cream, foregroundColor: _ink, elevation: 0),
      inputDecorationTheme: InputDecorationTheme(filled: true, fillColor: Colors.white, border: OutlineInputBorder(borderRadius: BorderRadius.circular(16), borderSide: BorderSide.none), contentPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 14))),
    home: const MainShell(),
  );
}

class MainShell extends StatefulWidget { const MainShell({super.key}); @override State<MainShell> createState() => _MainShellState(); }
